For every integer $n\ge1$,
\begin{equation}
 a(n+1)=\prod_{k=1}^{n}
 \left(1-2\left(\floor{\frac{k^n}{n}}
                  -\floor{\frac{k^n-1}{n}}\right)\right)
 =(-1)^{n/\rad(n)}
 =\begin{cases}1,&4\mid n,\\-1,&4\nmid n.\end{cases}
\end{equation}
All division inside a floor is rational division; in particular the
subtraction by $1$ precedes the second division.

We have $I_0=1$, $I_1=1/2$, and, for $m\ge2$,
\begin{equation}
 I_m=\begin{cases}
 -1/(m^2-1),&m\ \text{even},\\
 1/(m+1),&m\equiv1\pmod4,\\
 -1/(m-1),&m\equiv3\pmod4.
 \end{cases}
\end{equation}
Consequently $a(0)=1$ and, for $m\ge1$, $a(m)=1$ exactly when
$m\equiv1\pmod4$, and $a(m)=-1$ otherwise. Also
\begin{equation}
 d(0)=1,\qquad
 d(m)=\begin{cases}
 m^2-1,&m\ge2\ \text{even},\\
 m+1,&m\equiv1\pmod4,\\
 m-1,&m\equiv3\pmod4.
 \end{cases}
\end{equation}
The odd branches include $m=1$ in the second case.

For positive integers $k,s$, the group $\Gk$ has an $s$-spanning pair
if and only if one of the following conditions holds:
\begin{align*}
&s\text{ is odd}, &&2k\le s^2-1;\\
&s\text{ is even}, &&2k\le s^2-s;\\
&s\equiv0\pmod4,\quad k\text{ is even},
&&s^2-s<2k\le s^2;\\
&s\equiv2\pmod4,\quad k\equiv2\pmod4,
&&s^2-s<2k\le s^2.
\end{align*}

For every real $r\geq3$, the triangle of step $m=-r$ satisfies
\begin{enumerate}
\item $T_{-r}(n,k)>0$ for every positive even $n$ and $1\leq k\leq n$;
\item $T_{-r}(n,k)<0$ for every odd $n\geq3$ and $1<k<n$.
\end{enumerate}
In particular, the three OEIS conjectures and Conjecture~2 of
\cite{chen} hold for their stated integer parameters.

For integer $m$, every positive even row is entrywise nonnegative
if and only if $m\leq-3$ or $m\geq0$. For exactly these parameters,
every positive even row is in fact strictly positive.

For the state \eqref{eq:rho},
\begin{equation}
 \E(\rho)\le\frac{417965512477}{90316800000000}
 <\min_{S(a,b,d)\in\Sep_3}\D(\rho,S(a,b,d))
 =\frac{109}{23520}.
\end{equation}
Thus Eqs.~(A8), (A11), and their common form in Eq.~(16) of \cite{CAW}
do not contain a closest fully separable state at this instance.

For all $n,k\geq1$,
\begin{equation}
 T(n,k)=b(n)+b(k)-2.
\end{equation}
Consequently,
\begin{equation}
 a(2m+1)=2^{m+1}+4,\qquad a(2m+2)=3\cdot2^m+4\quad(m\geq0),
\end{equation}
and $\sum_{n\geq1}a(n)x^n=x(6+x-11x^2)/((1-x)(1-2x^2))$.

If $X_1,\ldots,X_n$ are independent geometric random variables on
$\{1,2,\ldots\}$ with success probability $p\in(0,1]$ and $q=1-p$, then
\begin{equation}
 \E\Dstar(X)=
 \sum_{j=1}^{n}\frac{(-1)^{j+1}\binom nj}{1-q^j}
 +\frac{n-2}{p}-\frac{n-1}{p(2-p)}.
\end{equation}

If $A\in\mathcal M(E)$ has $\nssp$ and $E$ has $c$ weak components,
including isolated vertices, then
\begin{equation}
 n\ \leq\ \dim_\R\Zc(A)\ \leq\ \dim\ker B
   =m-n+c,\qquad m\geq2n-c.
\end{equation}

For $n,k\geq0$ and $m\geq1$, put $N=n+m$.
The following identities also hold at $m=0$ with empty products:
\begin{align}
B(n,k,m)&=\Schur_{(k^m)}(1,2,\ldots,N)\\
&=\frac{1}{\prod_{i=0}^{m-1}(n+i)!}
\sum_{n\geq j_1\geq\cdots\geq j_m\geq0}
(-1)^{\sum_tj_t}
\prod_{1\leq q<p\leq m}(j_q-j_p+p-q)^2\notag\\[-2pt]
&\hspace{32mm}\cdot
\prod_{t=1}^{m}
\frac{(n+t-1)_{\underline{j_t}}(n-j_t+t)^{n+k}}
{(j_t+m-t)!}.
\end{align}

For $n,m\geq1$ and any integer $a$, with $N=n+m$,
\begin{equation}
F(n,m;a)=
\begin{cases}
\Schur_{((a-n)^m)}(1,\ldots,N),&a\geq n,\\
0,&-m<a<n,\\
\displaystyle\frac{(-1)^{nm}}{(N!)^{m+r}}
\Schur_{(r^n)}(1,\ldots,N),&a=-m-r,\quad r\geq0.
\end{cases}
\end{equation}
For $n=0$, instead $F(0,m;a)=(m!)^a$ for every integer $a$.

For $n\geq0,m\geq1$, Kurkov's FORMULA conjecture in OEIS A132393,
dated 24 May 2026, holds:
\begin{equation}
\stir{n+m+1}{m+1}=(n+m)!\prod_{t=1}^m(n+t)^t\,R(n,m).
\end{equation}

For every integer $n\geq0$,
\begin{equation}
a_n=4\bin{2n+4}{n+2}+4\bin{2n+2}{n+1}+\bin{2n}{n}
       -72\cdot2^n+16n+40.
\end{equation}
Consequently, for every integer $n\geq6$,
\begin{equation}
\begin{aligned}
0={}&2(n+2)a_n-(17n+23)a_{n-1}+(47n+36)a_{n-2}\\
 &-2(22n+17)a_{n-3}+4(20-n)a_{n-4}\\
 &+8(2n-9)a_{n-5}+24(12n-47).
\end{aligned}
\end{equation}

Let $u_n=T(2n,n)$ for $n\geq0$ (A027171), and
$v_n=T(2n-1,n-1)$ for $n\geq1$ (A027175). Then
\begin{equation}
2(n+1)f_n-(7n+5)f_{n-1}+2(3-2n)f_{n-2}+12(1-3n)=0
\end{equation}
holds for $f=u$, $n\geq2$, and for $f=v$, $n\geq3$.

For $b_n=\sum_{k=0}^{\lfloor n/2\rfloor}T(n,k)$, $n\geq0$ (A027179),
put
\begin{align*}
p_0(n)&=-(n+2)(3n-20),&p_1(n)&=-(n+1)(3n-11),\\
p_2(n)&=33n^2-180n-100,&p_3(n)&=15n^2-56n+1,\\
p_4(n)&=2(-51n^2+313n-208),&p_5(n)&=-12(n-1)(n-4),\\
p_6(n)&=8(9n-11)(n-5).
\end{align*}
Then Mathar's seven-term recurrence holds for every $n\geq6$:
\begin{equation}
\sum_{j=0}^6p_j(n)b_{n-j}+4(-24n^2+196n-365)=0.
\end{equation}

Let $n\ge3$, $\|z\|=1$, and $\langle z,x\rangle=\langle z,y\rangle=0$.
For arbitrary real symmetric off-diagonal weights $a_{ij}$,
\begin{equation}
 \sum_{i<j}a_{ij}p_{ij}^{\,2}
 \ \le\ \sum_{i<j<k}\max\{a_{ij},a_{ik},a_{jk}\}\,q_{ijk}^{\,2}.
\end{equation}
In particular, this proves the inequality for every real orthonormal triple
and every positive-entry symmetric matrix.

Under the vector hypotheses of Theorem~\ref{thm:main}, every pair family satisfies
\begin{equation}
 \sum_{\{i,j\}\in F,\ i<j}p_{ij}^2
 \ \le\ \sum_{\{i,j,k\}\in N(F),\ i<j<k}q_{ijk}^2.
\end{equation}

Let $A\in\R^{n\times n}$ be symmetric and $x\in\R^n$ satisfy
$\Delta=x^{\mathsf T}Ax\ne0$. Put $w=Ax$ and
$M=A-ww^{\mathsf T}/\Delta$. Then
\begin{equation}
\In(M)=
\begin{cases}
(n_+(A)-1,\ n_-(A),\ n_0(A)+1),&\Delta>0,\\
(n_+(A),\ n_-(A)-1,\ n_0(A)+1),&\Delta<0.
\end{cases}
\end{equation}
Moreover,
\begin{equation}
\ker M=\ker A\oplus\Span\{x\},\qquad \rank M=\rank A-1.
\end{equation}

Let $Y$ be a nonempty connected topological space, and let
$d,x:Y\to\R^n$ be continuous. For $y\in Y$ define
\begin{align*}
D(y)&=\diag(d_1(y),\ldots,d_n(y)),\qquad
\Delta(y)=x(y)^{\mathsf T}D(y)x(y),\\
M(y)&=D(y)-\frac{D(y)x(y)x(y)^{\mathsf T}D(y)}{\Delta(y)}.
\end{align*}
Suppose $\Delta(y)\ne0$ and $M(y)\succeq0$ for every $y$.
Then exactly one of the following alternatives holds:
\begin{enumerate}
\item $\Delta(y)>0$ and every $d_i(y)\ge0$ for all $y$;
\item $\Delta(y)<0$ for all $y$, and there is a unique index $j$ such that
      $d_j(y)<0$ for every $y$ and $d_i(y)\ge0$ for every $i\ne j$ and every $y$.
\end{enumerate}

The reduced numerators of $b_n$ repeat the block $(0,1,1,1,0,-1)$, with
least period six. For $n\ge12$,
\begin{equation}
 a_n=2a_{n-6}-a_{n-12}.
\end{equation}
Moreover, the ordinary generating function of the denominator sequence is
\begin{equation}
 \sum_{n\ge0}a_nz^n=
 \frac{1+z+z^2+2z^3+z^4+6z^5-z^6+2z^7+z^8+z^9-z^{10}}
 {(1-z^6)^2}.
\end{equation}
This is the generating function recorded as empirical by Colin Barker on
November 11, 2016, in A189733's FORMULA field.

For every $n\ge0$,
\begin{equation}
 B(n,0)=\sum_{j=0}^n(-1)^{n-j}\binom nj b_j=(-1)^{n+1}b_n.
\end{equation}

For $m\ge0$ and $d\ge1$,
\begin{equation}
 B(m,m+d)=(-1)^m\sum_{j=0}^{\lfloor(d-1)/2\rfloor}
 \frac{(-1)^j\binom{d-1-j}{j}}{m+j+1}.
\end{equation}
Together with $B(m,m)=0$ and
$B(m,n)=(-1)^{m+n+1}B(n,m)$, this determines the whole square array.

For all $n\ge0$,
\begin{align}
 \sum_{n\ge0}p_nz^n
 &=\frac{z+z^2+z^3-z^5}{1-z^6}
 =\frac{z(1+z^2-z^3)}{(1-z)(1-z+z^2)(1+z+z^2)},\\

 p_n&=\frac{1+(-1)^{\lfloor(n-1)/3\rfloor}}2
       -\left\lfloor\frac{n+1}{6}\right\rfloor
       +\left\lfloor\frac n6\right\rfloor.
\end{align}
For $n\ge5$,
\begin{equation}
 p_n=p_{n-1}-p_{n-2}+p_{n-3}-p_{n-4}+p_{n-5}.
\end{equation}
These are A278718's generating function and Hurt's formulas dated
October 3, 2017.

For every $k\ge0$,
\begin{equation}
 (c_{6k},\ldots,c_{6k+5})=(6k+1,2,3,2,6k+5,1).
\end{equation}
In particular, $c_n=2c_{n-6}-c_{n-12}$ for $n\ge12$, and
\begin{equation}
 \sum_{n\ge0}c_nz^n=
 \frac{\begin{gathered}1+2z+3z^2+2z^3+5z^4+z^5\\
       {}+5z^6-2z^7-3z^8-2z^9+z^{10}-z^{11}\end{gathered}}
      {(1-z^6)^2}.
\end{equation}
Thus both conjectures attributed to Barker on January 10, 2016, in
A267068 are true. Its other three FORMULA assertions hold, with the
OEIS offsets of the cited sequences~\cite{auxiliary}:
\begin{align}
 c_{2n+1}&=\mathrm{A130196}(n+1),\notag\\
 c_{\mathrm{A047245}(n+1)}&=\mathrm{A052901}(n+2),\\
 c_{3n}+c_{3n+1}+c_{3n+2}&=\mathrm{A047238}(n+3)\qquad(n\ge0).\notag
\end{align}

If $2\leq k\leq n$ and $2k>n$, then
\begin{equation}
 \Der_n-T(n,k)=\binom nk(k-1)!\Der_{n-k}
             =\frac{n!}{k(n-k)!}\Der_{n-k}.
\end{equation}

For every $n\geq0$, the largest signed coefficient of $H_n$ is unique, and
\begin{equation}
 q(n)=\floor{\frac{2n+7-\sqrt{8n+21}}8},\qquad a(n)=n-4q(n).
\end{equation}
Equivalently, $a(n)$ is the least nonnegative integer $j\equiv n\pmod4$
such that
\begin{equation}
 F(j):=j^2+7j+7\ \geq\ 2n.
\end{equation}
Moreover, $a(n+1)-a(n)\in\{1,-3\}$ for every $n\geq0$.

The integer $b(n)$ is the least nonnegative $j\equiv n\pmod2$ satisfying
\begin{equation}
 j^2+5j+2\geq2n.
\end{equation}
For every $n\geq0$, $b(n+1)-b(n)\in\{1,-1\}$.
There are two absolute maxima exactly at the degrees
\begin{equation}
 N_m=2m(m+2)+(m+1)(-1)^{m+1},\qquad m\geq1,
\end{equation}
in increasing order. At every other degree there is one absolute maximum.

For every integer $n\geq1$, all $T(n,k)$ are integers, $T(n,k)=0$ for
$k>B_n$, and
\begin{equation}
 -\sum_{k=0}^{B_n}(-1)^k T(n,k)
 =2\round\!\left(\frac{2^n}{3}\right)=2J_n.
\end{equation}

For every $n\geq1$ and $k\geq0$,
\begin{equation}
 T(n,k)=[y^k]P_n(y),\qquad
 P_n(y)=-1+\sum_{h=1}^{n}y^h(1-y^h)^{n-h}\in\Z[y].
\end{equation}
Moreover, $\deg P_n\leq B_n$.

For $n\geq1$, $T(n,0)=-1$, and for every $k\geq1$,
\begin{equation}
 T(n,k)=\sum_{\substack{h\mid k\\1\leq h\leq n}}
 (-1)^{k/h-1}\binom{n-h}{k/h-1}.
\end{equation}

For every $n\geq2$ and $v\in V$, the integer $E_n(v)$ is positive and
\begin{align}
 T(n,n^2+1)&=nE_n(v),\\
 T(n,n^2)&=(2n-1)E_n(v).
\end{align}
Consequently $T(n,n^2+1)>0$ and
\[
 \frac{T(n,n^2)}{T(n,n^2+1)}=\frac{2n-1}{n}.
\]
Moreover, for every $n\geq1$,
\begin{equation}
 T(n,n+1)=n!,\qquad T(n,n^2+1)=(n!)^n.
\end{equation}

A length-$(n^2-1)$ trail from $v$ visits every vertex. If its missing edge
is $(a,b)$ and its endpoint is $t$, exactly one of the following holds:
\begin{enumerate}
\item $b=v$ and $a=t$;
\item $a=b\ne v$ and $t=v$.
\end{enumerate}

For $0\le k<m$,
\begin{equation}
\norm{A_k}\le6\,2^{k/2},\qquad
\frac{\norm{C_{m,k}}}{2^{m/2}}
\le3\sqrt2\,2^{-k/2}.
\end{equation}

Writing $t=m-k$, one has
\begin{equation}
Q_{m,k}=(1-2^{-t})D_k+t\,2^{-m}F_k,
\qquad
\norm{Q_{m,k}-D_k}\le3(1+2t)2^{-t}.
\end{equation}

Counterexamples exist for every $N\ge3$. For the distributions in
Theorem~\ref{thm:main}, $S_\alpha(q)>S_\alpha(p)$ holds exactly for
$0\le\alpha<\alpha_*$, where $\alpha_*>1$ is the unique root above one of
\begin{equation}
 (9/4)^{\alpha_*}+7\,4^{-\alpha_*}=4.
\end{equation}
Here $S_0$ is log support size and $S_1=\HH$;
numerically $\alpha_*\simeq1.262623$.
No dimension-independent additive correction repairs the Shannon bound.

For every normalized state, support matrix $R$ of rank $k$, and
admissible $Q',c$, one has
\begin{equation}
 \HH(p_{Q',c,R})\ \ge\ -\log\sum_{d,t}q_R(d,t)^2.
\end{equation}
